#include "logos_store.h"
#include <fstream>
namespace logos {
Status ledger_replay(const Ledger&l,ReplayFn fn,void*ctx){std::ifstream f(l.path,std::ios::binary);if(!f)return std::filesystem::exists(l.path)?Status::IOError:Status::Ok;u64 expected=1;Digest256 prev{};Buffer rec(152);for(;;){f.read((char*)rec.data(),152);auto got=f.gcount();if(got==0)break;if(got!=152)return Status::LedgerCorrupt;LglRecord r{};auto st=lgl_parse({rec.data(),152},&r);if(st!=Status::Ok)return st;if(r.sequence!=expected)return Status::LedgerSequence;if(r.previous_event_hash!=prev)return Status::LedgerChain;if(fn&&(st=fn(r,ctx))!=Status::Ok)return st;prev=r.event_hash;expected++;}return Status::Ok;}struct ScanCtx{u64 count{};Digest256 last{};};static Status scan_cb(const LglRecord&r,void*p){auto*c=(ScanCtx*)p;c->count=r.sequence;c->last=r.event_hash;return Status::Ok;}Status ledger_open(const std::filesystem::path&p,Ledger*out){if(!out)return Status::InvalidArgument;std::error_code ec;std::filesystem::create_directories(p.parent_path(),ec);if(ec)return Status::IOError;if(!std::filesystem::exists(p)){std::ofstream create(p,std::ios::binary);if(!create)return Status::IOError;}out->path=p;ScanCtx c{};auto st=ledger_replay(*out,scan_cb,&c);if(st!=Status::Ok)return st;out->next_sequence=c.count+1;out->previous_hash=c.last;return Status::Ok;}Status ledger_append(Ledger*l,EventType t,const Digest256&payload,std::string_view target,Digest256*event_hash){if(!l)return Status::InvalidArgument;Buffer rec;Digest256 eh{};auto st=lgl_encode(t,l->next_sequence,l->previous_hash,payload,target,&rec,&eh);if(st!=Status::Ok)return st;std::ofstream f(l->path,std::ios::binary|std::ios::app);if(!f)return Status::IOError;f.write((const char*)rec.data(),(std::streamsize)rec.size());f.flush();if(!f)return Status::IOError;l->next_sequence++;l->previous_hash=eh;if(event_hash)*event_hash=eh;return Status::Ok;}Status ledger_count(const Ledger&l,u64*out){if(!out)return Status::InvalidArgument;ScanCtx c{};auto st=ledger_replay(l,scan_cb,&c);if(st==Status::Ok)*out=c.count;return st;}
}
